  <footer style="padding:18px;border-top:1px solid #eef3ef;color:var(--muted)">
    <div>&copy; {{BUSINESS_NAME}} — Not a medical provider network. For emergencies call local services.</div>
  </footer>

  <script>
    (function(){
      const map = {
        clarity:{label:'Clarity Session',value:'clarity',cta:'Book Clarity Session'},
        coping:{label:'Skills Block',value:'coping',cta:'Book a Skills Session'},
        ongoing:{label:'Ongoing Therapy',value:'ongoing',cta:'Request Ongoing Sessions'},
        urgent:{label:'Stabilization',value:'urgent',cta:'Request Stabilization Support'}
      };

      // side choices
      document.querySelectorAll('.choice').forEach(b=>{
        b.addEventListener('click',()=>{
          const key = b.getAttribute('data-key');
          const info = map[key];
          document.getElementById('side-suggest').textContent = info.label + ' — ' + info.cta;
          document.getElementById('suggested-path').value = info.value;
          document.getElementById('submit-btn').textContent = info.cta;
        });
      });

      // select sync
      const sel = document.getElementById('mood-select');
      sel.addEventListener('change', ()=>{
        const v = sel.value;
        let key = 'clarity';
        if(v==='coping') key='coping';
        if(v==='ongoing') key='ongoing';
        if(v==='urgent') key='urgent';
        const info = map[key];
        document.getElementById('side-suggest').textContent = info.label + ' — ' + info.cta;
        document.getElementById('suggested-path').value = info.value;
        document.getElementById('submit-btn').textContent = info.cta;
      });

      // form submit (client-side only)
      document.getElementById('booking-form').addEventListener('submit', function(e){
        e.preventDefault();
        const name = document.getElementById('name').value || '';
        const email = document.getElementById('email').value || '';
        const notes = document.getElementById('notes').value || '';
        const path = document.getElementById('suggested-path').value || '';

        // Compose a mailto as a graceful fallback so user can send request via their email client.
        const subject = encodeURIComponent('Request: ' + (path || 'Appointment') + ' from ' + name);
        const body = encodeURIComponent('Name: ' + name + '\nEmail: ' + email + '\nSuggested path: ' + path + '\nNotes:\n' + notes + '\n\n(Please reply with available times.)');
        const mailto = 'mailto:{{EMAIL}}?subject=' + subject + '&body=' + body;

        // Open mail client as a clear action and also show a quick confirmation.
        window.location.href = mailto;
      });

      // accordion
      document.querySelectorAll('.acc-trigger').forEach(t=>{
        t.addEventListener('click', ()=>{
          const expanded = t.getAttribute('aria-expanded') === 'true';
          t.setAttribute('aria-expanded', String(!expanded));
          const panel = t.nextElementSibling;
          panel.style.display = expanded ? 'none' : 'block';
        });
      });

    })();
  </script>
